extension AppLocalizationsX on BuildContext {
  AppLocalizations get l10n =>
      Localizations.of<AppLocalizations>(this, AppLocalizations) ??
      AppLocalizations.fallback();
}

class _AppLocalizationsDelegate
    extends LocalizationsDelegate<AppLocalizations> {
  const _AppLocalizationsDelegate();

  @override
  bool isSupported(Locale locale) {
    if (locale.languageCode.toLowerCase() == 'es') return true;
    return AppLocalizations.supportedLocales.any(
      (supported) =>
          supported.languageCode == locale.languageCode &&
          (locale.countryCode == null ||
              supported.countryCode == null ||
              supported.countryCode == locale.countryCode),
    );
  }

  @override
  Future<AppLocalizations> load(Locale locale) async => AppLocalizations(
    AppLocalizations.localeForCode(
      locale.countryCode == null
          ? locale.languageCode
          : '${locale.languageCode}-${locale.countryCode}',
    ),
  );

  @override
  bool shouldReload(_AppLocalizationsDelegate old) => false;
}

class AppLanguageOption {
  const AppLanguageOption(this.code, this.label);

  final String code;
  final String label;
}
